<template>
  <div class="pre-reference reference-business-list">
    <div class="reference-crumb">首页 / 销售 / <b>预下单</b></div>
    <section class="pre-reference-panel">
      <div class="pre-list-filters"><label>预下单号<input v-model="q" placeholder="搜索预下单号" @input="prePage=1" /></label><label>客户<input v-model="customerSearch" placeholder="搜索客户" @input="prePage=1" /></label><label>审批状态<select v-model="approvalSearch" @change="prePage=1"><option value="">全部</option><option value="approved">财务已通过</option><option value="none">财务未通过 / 未提交</option></select></label><button @click="resetList">重置</button></div>
      <div class="pre-reference-toolbar"><button v-action="['pre-orders','create']" v-if="canWrite" class="pre-accent" @click="openCreate()">新增预下单</button><button v-for="t in preTabs" :key="t.key" class="pre-accent" :class="{active:preTab===t.key}" @click="preTab=t.key;prePage=1">{{ t.label }} ({{ t.count }})</button><button class="pre-config" @click="configOpen=true">⚙ 配置</button><ReferencePager v-model:page="prePage" v-model:page-size="preSize" :total="filteredPre.length" @refresh="load()" /></div>
      <div class="pre-list-scroll"><table class="pre-list-table"><thead><tr><th v-for="c in visiblePreColumns" :key="c.key">{{ c.label }}</th></tr></thead><tbody><tr v-for="row in prePageRows" :key="row.id"><td v-for="c in visiblePreColumns" :key="c.key">
        <template v-if="c.key==='order'"><button class="pre-link" @click="detailRow=row">{{ row.order_no||row.pre_order_no }}</button><TrialNotice :record="row" /></template><template v-else-if="c.key==='customer'">{{ row.customer_name }}</template><template v-else-if="c.key==='manager'">{{ row.manager||'—' }}</template>
        <div v-else-if="c.key==='styles'" class="pre-style-names"><button v-for="item in row.items" :key="item.id" class="pre-link" @click="detailRow=row">{{ item.style_no||item.product_name||'图片新款（待版房命名）' }}</button></div>
        <div v-else-if="c.key==='photos'" class="pre-list-images"><button v-for="item in row.items.filter(i=>i.effect_image_url)" :key="item.id" @click="openImage(item.effect_image_url,item.style_no||item.product_name)"><img :src="item.effect_image_url" alt="成品图片" /></button><span v-if="!row.items.some(i=>i.effect_image_url)">—</span></div>
        <template v-else-if="c.key==='due'">{{ row.target_date||'—' }}</template><span v-else-if="c.key==='requirements'" class="pre-req-preview" :title="row.requirements">{{ row.requirements||'—' }}</span><template v-else-if="c.key==='created'">{{ fmtTime(row.created_at) }}</template><button v-else class="pre-link" @click="detailRow=row">详情</button>
      </td></tr><tr v-if="!filteredPre.length"><td :colspan="visiblePreColumns.length" class="pre-list-empty">暂无符合条件的预下单</td></tr></tbody></table></div>
    </section>
    <div v-if="configOpen" class="modal-mask"><div class="modal" style="width:480px"><div class="modal-head"><h3>预下单列表配置</h3><button class="x" @click="configOpen=false">×</button></div><div class="modal-body pre-column-options"><label v-for="c in preColumns" :key="c.key"><input type="checkbox" v-model="selectedColumns" :value="c.key" :disabled="selectedColumns.length===1&&selectedColumns.includes(c.key)" />{{ c.label }}</label></div><div class="modal-foot"><button @click="saveListConfig">保存</button></div></div></div>
    <div v-if="detailRow" class="modal-mask"><section class="modal pre-reference-detail"><div class="modal-head"><h3>预下单详情 · {{ detailRow.order_no||detailRow.pre_order_no }}</h3><button class="x" @click="detailRow=null">×</button></div><div class="modal-body"><TrialNotice :record="detailRow" /><div class="pre-detail-meta"><span>客户：{{ detailRow.customer_name }}</span><span>业务员：{{ detailRow.manager||'—' }}</span><span>目标交期：{{ detailRow.target_date||'—' }}</span><span>状态：{{ statusLabel(detailRow.status) }}</span><span>订单总金额：{{ detailRow.total_usd==null?'—':'USD '+Number(detailRow.total_usd).toFixed(2) }}</span><span>付款比例：{{ detailRow.payment_ratio==null?'—':detailRow.payment_ratio+'%' }}</span><span>联系人：{{ detailRow.recipient_name||'—' }}</span><span>电话：{{ detailRow.recipient_phone||'—' }}</span><span class="full">收货地址：{{ detailRow.shipping_address||'—' }}</span></div><p class="pre-detail-requirements">客户要求：{{ detailRow.requirements||'—' }}</p><article v-for="item in detailRow.items" :key="item.id" class="pre-detail-style"><img v-if="item.effect_image_url" :src="item.effect_image_url" @click="openImage(item.effect_image_url,item.style_no)" alt="款式图片" /><div><b>{{ item.style_no||item.product_name||'图片新款（待版房命名）' }}</b><p>{{ item.expected_qty }} 件 · {{ item.source_type==='archive'||item.development?.flow_status==='done'?'打版完成':'待开发 / 打版中' }}</p><p>{{ item.remark||'—' }}</p><table v-if="item.size_prices?.length" class="pre-saved-prices"><thead><tr><th>颜色</th><th>尺码</th><th>数量</th><th>单价 USD</th><th>金额 USD</th></tr></thead><tbody><tr v-for="(r,i) in item.size_prices" :key="i"><td>{{r.color||'待确认'}}</td><td>{{r.size}}</td><td>{{r.qty}}</td><td>{{Number(r.unit_price).toFixed(2)}}</td><td>{{Number(r.amount).toFixed(2)}}</td></tr></tbody></table><button v-if="item.development" class="pre-link" @click="router.push({path:'/pattern-board',query:{techpack:item.development.id}})">查看打版流程</button></div></article></div><div class="modal-foot"><button @click="detailRow=null">关闭</button><button v-action="['pre-orders','edit']" v-if="canWrite&&detailRow.status!=='converted'" @click="edit(detailRow);detailRow=null">编辑</button><button v-action="['pre-orders','complete']" v-if="canWrite&&detailRow.status==='open'" :disabled="busy" @click="complete(detailRow)">完成预下单</button><button v-if="canWrite&&detailRow.status==='ready'&&detailRow.pattern_complete_unordered" class="pre-accent" @click="toSales(detailRow)">转业务下单</button><button v-if="detailRow.converted_order_id" class="pre-accent" @click="router.push({path:'/orders',query:{order:detailRow.converted_order_id}})">查看正式订单</button></div></section></div>
    <div v-if="showForm" class="modal-mask pre-entry-mask"><form ref="formElement" class="modal xwide pre-form" role="dialog" aria-modal="true" aria-label="新增或编辑预下单" @submit.prevent="save(false)">
      <div class="modal-head"><h3>{{ form.id ? '编辑预下单' : '新增预下单' }}</h3><button type="button" class="x" :disabled="busy||uploading>0" @click="closeForm()">×</button></div>
      <div class="modal-body">
      <div class="pre-style-toolbar"><h3>选择商品 · {{ form.items.length }} 款</h3><button type="button" class="btn btn-primary" :disabled="busy||uploading>0" @click="openArchivePicker()">从样衣管理选择商品</button><button type="button" class="btn btn-ghost" :disabled="form.items.length>=100 || busy || uploading>0" @click="form.items.push(blankItem())">＋ 添加图片新款</button></div>
      <PreOrderArchiveMatrix v-for="item in form.items.filter(i=>i.source_type==='archive')" :key="item.key||item.sample_archive_id" :item="item" :templates="sizeTemplates" @remove="form.items.splice(form.items.indexOf(item),1)"/>
      <PreOrderImageDrop :disabled="busy||archiveOpen" :remaining="remainingStyles" @images="addImages" @uploading="trackUpload" />
      <div class="pre-basics"><div class="form-grid">
        <div class="fitem"><label>订单号 <b class="req">*</b></label><input class="input" v-model.trim="form.order_no" maxlength="50" required placeholder="业务员手动填写，不能重复" /></div>
        <div class="fitem"><label>选择客户档案</label><select class="select" v-model.number="form.customer_id" @change="fillCustomer()"><option :value="null">暂未建档，手填客户名称</option><option v-for="customer in customers" :key="customer.id" :value="customer.id">{{ customer.name }}</option></select></div>
        <div class="fitem"><label>客户名称 <b class="req">*</b></label><input class="input" v-model.trim="form.customer_name" maxlength="255" required /></div>
        <div class="fitem"><label>联系人</label><input class="input" v-model="form.recipient_name" maxlength="255" /></div>
        <div class="fitem"><label>联系电话</label><input class="input" v-model="form.recipient_phone" maxlength="255" /></div>
        <div class="fitem"><label>业务员</label><input class="input" v-model="form.manager" maxlength="255" /></div>
        <div class="fitem full"><label>收货地址</label><input class="input" v-model="form.shipping_address" maxlength="2000" /></div>
        <div class="fitem"><label>目标交期</label><input class="input" v-model="form.target_date" type="date" /></div>
        <div v-for="field in metadataFields" :key="field.key" class="fitem"><label>{{field.label}}</label><input class="input" v-model.trim="form[field.key]" :maxlength="field.key==='po_no'?100:120" :placeholder="'填写'+field.label" :list="'pre-meta-'+field.key" /><datalist :id="'pre-meta-'+field.key"><option v-for="value in metadataOptions(field.key)" :key="value" :value="value" /></datalist></div>
        <div class="fitem"><label>订单总金额（USD）</label><input class="input" v-model="form.total_usd" :readonly="form.items.length>0&&form.items.every(i=>i.size_prices?.length)" :title="'全部款式录入尺码报价后自动汇总'" type="number" min="0" max="999999999999.99" step="0.01" placeholder="未约定可留空" /></div>
        <div class="fitem"><label>付款比例（%）</label><input class="input" v-model="form.payment_ratio" type="number" min="0" max="100" step="0.01" placeholder="例如 30 表示 30%" /></div>
        <div class="fitem"><label>约定付款金额（USD）</label><output class="pre-payment">{{agreedPayment===null?'—':agreedPayment.toFixed(2)}}</output><small class="sub">按总金额 × 付款比例计算，仅为约定，不代表已收款</small></div>
        <div class="fitem full"><label>订单 / 客户要求</label><textarea v-model="form.requirements" maxlength="4000" rows="2"></textarea></div>
      </div></div>
      <h3 class="pre-style-section-title">款式信息 · {{form.items.length}} 款（填写尺码、数量、单价）</h3>
      <div class="pre-style-grid"><section v-for="(item,index) in form.items" :key="item.id || item.client_key" class="pre-style" v-show="item.source_type!=='archive'">
        <div class="pre-style-head"><strong>第 {{ index+1 }} 款 · {{item.style_no || item.product_name || '图片新款（待命名）'}}</strong><span class="pre-style-actions"><button type="button" class="link-btn" :disabled="index===0||busy||uploading>0" @click="moveStyle(index,-1)">前移</button><button type="button" class="link-btn" :disabled="index===form.items.length-1||busy||uploading>0" @click="moveStyle(index,1)">后移</button></span><button  type="button" class="link-btn danger" :disabled="form.items.length===1 || busy || uploading>0" @click="form.items.splice(index,1)">删除此款</button></div>
        <StyleImageFields v-if="item.source_type!=='archive'" v-model:effect-image-url="item.effect_image_url" v-model:detail-images="item.detail_images" :disabled="busy||uploading>0" @uploading="trackUpload" />
        <div v-else class="archive-preview"><img v-if="item.effect_image_url" :src="item.effect_image_url" alt="已打版商品" class="archive-photo" /><p class="sub">复用该样衣锁定版本；原样衣及其他订单不受影响。</p></div>
        <div class="form-grid">
         <div class="fitem"><label>款式来源</label><select class="select" :disabled="busy||uploading>0" v-model="item.source_type" @change="changeSource(item)"><option value="new">上传图片新款（需开发打版）</option><option value="archive">选择已完成打版商品</option><option v-if="item.source_type==='legacy'" value="legacy">原有款式资料</option></select></div>
         <div v-if="item.source_type==='archive'" class="fitem"><label>已完成打版商品 <b class="req">*</b></label><select class="select archive-picker" v-model.number="item.sample_archive_id" @change="selectArchive(item)"><option :value="null">请选择锁定的样衣版本</option><option v-for="p in archiveProducts" :key="p.id" :value="p.id" :disabled="archiveChosen(p,item)">{{p.style_no}} · {{p.product_name}} · {{p.version}}</option></select></div>
         <div class="fitem"><label>款式名称 <span class="sub">{{item.source_type==='archive'?'从商品带入':'有图片时可不填'}}</span></label><input class="input" v-model.trim="item.product_name" maxlength="120" :readonly="item.source_type==='archive'" placeholder="图片新款可留空" /></div>
         <div class="fitem"><label>款号</label><input class="input" v-model.trim="item.style_no" maxlength="100" :readonly="item.source_type!=='legacy'" :placeholder="item.source_type==='archive'?'选择商品后带入':'由版房在开发打版过程中填写'" /></div>
         <div class="fitem"><label>预估数量</label><input class="input" v-model.number="item.expected_qty" :readonly="!!item.size_prices?.length" type="number" min="0" step="1" /></div><div class="fitem"><label>款式要求 / 备注</label><input class="input" v-model="item.remark" maxlength="2000" /></div>
        </div>
        <div class="pre-size-pricing"><div class="pre-template-tools"><label>尺码模板<select @change="applySizeTemplate(item,$event)"><option value="">选择模板添加尺码</option><option v-for="t in sizeTemplates" :key="t.id" :value="t.id">{{t.name}}</option></select></label></div><table><thead><tr><th>颜色（可选）</th><th>尺码</th><th>数量</th><th>单价 USD</th><th>金额 USD</th><th></th></tr></thead><tbody><tr v-for="(price,pi) in item.size_prices" :key="pi"><td><select v-model="price.color"><option value="">待确认</option><option v-for="c in [...new Set([...orderColorOptions,price.color].filter(Boolean))]" :key="c" :value="c">{{c}}</option></select></td><td><input v-model.trim="price.size" maxlength="50" placeholder="如 S / M" required /></td><td><input v-model.number="price.qty" type="number" min="0" max="1000000" step="1" required @input="syncQty(item)" /></td><td><input v-model.number="price.unit_price" type="number" min="0" max="10000000" step="0.01" required /></td><td>{{ priceAmount(price).toFixed(2) }}</td><td><button type="button" class="link-btn danger" @click="item.size_prices.splice(pi,1);syncQty(item)">×</button></td></tr></tbody></table><div class="pre-price-foot"><button type="button" class="link-btn"  @click="item.size_prices.push({color:'',size:'',qty:0,unit_price:0})">＋ 增加尺码</button><b>合计 {{ item.expected_qty||0 }} 件 · USD {{ styleAmount(item).toFixed(2) }}</b></div></div>
        <p v-if="item.source_type==='new'" class="sub">保存后自动关联开发单。<router-link v-if="item.development" :to="{path:'/pattern-board',query:{q:item.style_no||form.order_no}}">查看开发打版流程</router-link></p>
      </section></div><button type="button" class="btn btn-ghost" :disabled="form.items.length>=100 || busy || uploading>0" @click="form.items.push(blankItem())">＋ 添加一款</button>
      </div>
      <div class="modal-foot"><span class="sub">点击空白处后可 Ctrl+V 粘贴图片。尺码报价将随转单带入；未确认的颜色请在业务下单核对，未打版款仍须完成开发打版。</span><button type="button" class="btn btn-ghost" :disabled="busy||uploading>0" @click="closeForm()">取消</button><button class="btn btn-ghost" :disabled="busy||uploading>0">保存预下单</button></div>
    </form></div>
    <div v-if="archiveOpen" class="modal-mask pre-archive-mask"><section class="modal pre-archive-dialog" role="dialog" aria-modal="true" aria-label="选择已完成打版商品"><div class="modal-head"><h3>选择已完成打版商品</h3><button type="button" class="x" @click="archiveOpen=false">×</button></div><div class="modal-body"><input class="input" v-model="archiveQuery" placeholder="搜索款号 / 商品名称" /><p class="sub">仅列出已完成全部打版阶段、已锁定且没有待处理变更的最新样衣版本。</p><p v-if="archiveLoading" class="sub">正在读取样衣…</p><div v-else class="pre-archive-grid"><label v-for="product in filteredArchives" :key="product.id" :class="{selected:archiveSelection.includes(product.id)}"><input type="checkbox" :value="product.id" :disabled="archiveChosen(product)" v-model="archiveSelection" /><img v-if="product.image_url" :src="product.image_url" :alt="product.product_name" /><span v-else class="pre-no-photo">暂无图片</span><b>{{product.style_no || product.archive_no}}</b><span>{{product.product_name}}</span><small>{{product.version}}</small></label></div><p v-if="!archiveLoading&&!filteredArchives.length" class="sub">暂无符合条件的已完成打版商品。</p></div><div class="modal-foot"><span class="sub">已选 {{archiveSelection.length}} 款</span><button class="btn btn-ghost" @click="archiveOpen=false">关闭</button><button class="btn btn-primary" :disabled="archiveLoading||!archiveSelection.length" @click="addArchives()">添加到预下单</button></div></section></div>
  </div>
</template>
<script setup>
import {entryId} from '../utils/orderEntry';
import {orderColorOptions} from '../utils/orderOptions';
import TrialNotice from '../components/TrialNotice.vue';
import PreOrderArchiveMatrix from '../components/PreOrderArchiveMatrix.vue';
import PreOrderImageDrop from '../components/PreOrderImageDrop.vue';
import {auth} from '../store/auth';
import {computed,onMounted,reactive,ref,watch} from 'vue';import {useRouter} from 'vue-router';import {api} from '../api';import {can,canAction,permState} from '../store/permissions';import StyleImageFields from '../components/StyleImageFields.vue';import ReferencePager from '../components/ReferencePager.vue';import {fmtTime} from '../utils/time';import {openImage} from '../store/viewer';
const router=useRouter(),rows=ref([]),customers=ref([]),archiveProducts=ref([]),sizeTemplates=ref([]),q=ref(''),showForm=ref(false),busy=ref(false);const canWrite=computed(()=>permState.positionDirect?['create','edit','complete'].some(a=>canAction('pre-orders',a)):can('order.create'));
const customerSearch=ref(''),approvalSearch=ref(''),preTab=ref('all'),prePage=ref(1),preSize=ref(12),detailRow=ref(null),configOpen=ref(false);
const preColumns=[{key:'order',label:'预下单号'},{key:'customer',label:'客户名称'},{key:'manager',label:'业务员'},{key:'styles',label:'款式明细'},{key:'photos',label:'成品图片'},{key:'due',label:'目标交期'},{key:'requirements',label:'客户要求'},{key:'created',label:'提交时间'},{key:'actions',label:'操作'}];
function readColumns(){try{const saved=JSON.parse(localStorage.getItem('erp_preorder_columns'));if(Array.isArray(saved)){const valid=saved.filter(k=>preColumns.some(c=>c.key===k));if(valid.length)return valid;}}catch{}return preColumns.map(c=>c.key);}
const selectedColumns=ref(readColumns()),visiblePreColumns=computed(()=>preColumns.filter(c=>selectedColumns.value.includes(c.key)));
function saveListConfig(){try{localStorage.setItem('erp_preorder_columns',JSON.stringify(selectedColumns.value));}catch{}configOpen.value=false;}
const preBase=computed(()=>rows.value.filter(r=>(!q.value||[r.order_no,r.pre_order_no].some(v=>String(v||'').toLowerCase().includes(q.value.trim().toLowerCase())))&&(!customerSearch.value||String(r.customer_name||'').toLowerCase().includes(customerSearch.value.trim().toLowerCase()))&&(!approvalSearch.value||(approvalSearch.value==='approved'?r.finance_passed:!r.finance_passed))));
const preDefinitions=[['all','全部',()=>true],['finance','财务通过',r=>r.finance_passed],['missing','未填资料订单',r=>r.missing_details],['pattern','打版中',r=>r.pattern_running],['unordered','打版完成未下单',r=>r.pattern_complete_unordered]];
const preTabs=computed(()=>preDefinitions.map(([key,label,match])=>({key,label,count:preBase.value.filter(match).length})));
const filteredPre=computed(()=>preBase.value.filter(preDefinitions.find(t=>t[0]===preTab.value)[2]));
const prePageRows=computed(()=>filteredPre.value.slice((prePage.value-1)*preSize.value,prePage.value*preSize.value));
function resetList(){q.value='';customerSearch.value='';approvalSearch.value='';preTab.value='all';prePage.value=1;}
let itemSequence=0;
const blankItem=()=>{const generated_name='新款-'+entryId().slice(0,12).toUpperCase();return ({generated_name,client_key:'pre-style-'+(++itemSequence),source_type:'new',sample_archive_id:null,product_name:generated_name,style_no:'',expected_qty:0,effect_image_url:'',detail_images:[],size_prices:[],remark:''});};
const blank=()=>({id:null,version:1,order_no:'',customer_id:null,customer_name:'',recipient_name:'',recipient_phone:'',shipping_address:'',manager:auth.user?.name||auth.user?.username||'',target_date:'',requirements:'',total_usd:null,payment_ratio:null,designer:'',category:'',series:'',wave:'',sample_source:'',po_no:'',items:[blankItem()]});const form=reactive(blank());

const formElement=ref(null);
const uploading=ref(0),archiveOpen=ref(false),archiveLoading=ref(false),archiveQuery=ref(''),archiveSelection=ref([]);
const metadataFields=[{key:'designer',label:'设计师'},{key:'category',label:'分类'},{key:'series',label:'系列'},{key:'sample_source',label:'样品来源'}];
function metadataOptions(key){return [...new Set(rows.value.map(row=>row[key]).filter(Boolean))];}
const isEmptyItem=item=>!item.id&&item.source_type==='new'&&(!item.product_name||item.product_name===item.generated_name)&&!item.style_no&&!item.effect_image_url&&!item.detail_images.length&&!item.size_prices?.length&&!item.expected_qty&&!item.remark;
const remainingStyles=computed(()=>100-form.items.length+(form.items.some(isEmptyItem)?1:0));
const priceAmount=r=>Math.round(Number(r.qty||0)*Math.round(Number(r.unit_price||0)*100))/100;
const styleAmount=item=>(item.size_prices||[]).reduce((n,r)=>n+Math.round(priceAmount(r)*100),0)/100;
function syncQty(item){if(item.size_prices.length)item.expected_qty=item.size_prices.reduce((n,r)=>n+Number(r.qty||0),0);}
watch(()=>form.items.map(i=>({rows:i.size_prices||[],value:styleAmount(i)})),()=>{form.items.forEach(syncQty);if(form.items.length&&form.items.every(i=>i.size_prices?.length))form.total_usd=Math.round(form.items.reduce((n,i)=>n+styleAmount(i),0)*100)/100;},{deep:true});
const agreedPayment=computed(()=>form.total_usd!==null&&form.total_usd!==''&&form.payment_ratio!==null&&form.payment_ratio!==''?Math.round(Number(form.total_usd)*Number(form.payment_ratio))/100:null);
const filteredArchives=computed(()=>archiveProducts.value.filter(p=>!archiveQuery.value.trim()||[p.style_no,p.product_name,p.archive_no].some(v=>String(v||'').toLowerCase().includes(archiveQuery.value.trim().toLowerCase()))));
function trackUpload(active){uploading.value=Math.max(0,uploading.value+(active?1:-1));}
function closeForm(){if(!busy.value&&!uploading.value)showForm.value=false;}
function addItem(item){const empty=form.items.findIndex(isEmptyItem);if(empty>=0)form.items.splice(empty,1,item);else if(form.items.length<100)form.items.push(item);}
function addImages(urls){for(const url of urls)addItem({...blankItem(),effect_image_url:url});}
function moveStyle(index,delta){if(busy.value||uploading.value)return;const item=form.items.splice(index,1)[0];form.items.splice(index+delta,0,item);}
async function openArchivePicker(){archiveOpen.value=true;archiveSelection.value=[];archiveQuery.value='';archiveLoading.value=true;try{archiveProducts.value=await api.preOrderProducts();}catch(e){archiveProducts.value=[];alert(e.message);}finally{archiveLoading.value=false;}}
function addArchives(){if(archiveSelection.value.length>remainingStyles.value)return alert('每张预下单最多100款，请减少所选商品');for(const id of archiveSelection.value){const item={...blankItem(),source_type:'archive',sample_archive_id:id};selectArchive(item);addItem(item);}archiveOpen.value=false;}

const statusLabel=status=>({open:'录入中',ready:'待转业务下单',converted:'已转正式订单'})[status]||status;
async function load(){try{rows.value=await api.preOrders({});if(detailRow.value)detailRow.value=rows.value.find(r=>r.id===detailRow.value.id)||null;}catch(e){alert(e.message);}}
function fillCustomer(){const c=customers.value.find(c=>c.id===form.customer_id);if(c)Object.assign(form,{customer_name:c.name,recipient_name:c.contact||'',recipient_phone:c.phone||'',shipping_address:c.shipping_address||''});}
function changeSource(item){if(item.source_type==='archive'){item.sample_archive_id=null;}else{item.sample_archive_id=null;item.style_no='';}item.product_name='';item.effect_image_url='';item.detail_images=[];}
function archiveChosen(p,current){return form.items.some(i=>i!==current&&((i.sample_archive_id&&Number(i.sample_archive_id)===Number(p.id))||(p.style_no&&i.style_no?.trim().toLowerCase()===p.style_no.trim().toLowerCase())));}
function applySizeTemplate(item,event){const template=sizeTemplates.value.find(t=>String(t.id)===event.target.value);event.target.value='';if(!template)return;const names=[...new Set(String(template.sizes||'').split(/[,，]/).map(s=>s.trim()).filter(Boolean))];const color=item.size_prices[0]?.color||'印花001';const additions=names.filter(size=>!item.size_prices.some(r=>r.size===size&&r.color===color));item.size_prices.push(...additions.map(size=>({color,size,qty:0,unit_price:0})));syncQty(item);}
function selectArchive(item){const p=archiveProducts.value.find(p=>p.id===item.sample_archive_id);if(p&&archiveChosen(p,item)){item.sample_archive_id=null;return alert('同一款号不能重复选择');}if(p)Object.assign(item,{product_name:p.product_name,style_no:p.style_no,effect_image_url:p.image_url||'',detail_images:[]});}
function openCreate(){Object.assign(form,blank());showForm.value=true;}
function edit(row){Object.assign(form,blank(),JSON.parse(JSON.stringify(row)),{target_date:row.target_date||'',items:row.items.map(item=>({...blankItem(),...JSON.parse(JSON.stringify(item))}))});showForm.value=true;}
function toSales(row){router.push({path:'/orders',query:{pre_order:row.id}});}
async function complete(row){busy.value=true;try{await api.completePreOrder(row.id,{version:row.version});await load();}catch(e){alert(e.message);}finally{busy.value=false;}}
async function save(convert){if(busy.value||uploading.value>0)return;if(!formElement.value?.reportValidity())return;if(!form.order_no.trim()||!form.customer_name.trim()||form.items.some(i=>i.source_type==='archive'?!i.sample_archive_id:!i.product_name.trim()&&!i.effect_image_url&&!i.detail_images.length))return alert('请填写订单号、客户名称；每款须选择已打版商品或上传图片/填写名称');busy.value=true;try{const payload=JSON.parse(JSON.stringify(form));let saved=form.id?await api.updatePreOrder(form.id,payload):await api.createPreOrder(payload);Object.assign(form,saved);if(convert)saved=await api.completePreOrder(saved.id,{version:saved.version});showForm.value=false;await load();if(convert)toSales(saved);}catch(e){alert(e.message);}finally{busy.value=false;}}
onMounted(async()=>{await load();try{[customers.value,archiveProducts.value,sizeTemplates.value]=await Promise.all([api.customers({status:'active'}),api.preOrderProducts(),api.sizeTemplates()]);}catch(e){alert(e.message);}});
</script>
